import gleam/io
import gleam/list
import gleam/int
import core/matrix.{type Matrix}

pub fn distribute_batch(batch: List(Matrix), workers: Int) -> List(List(Matrix)) {
  let chunk_size = case workers > 0 {
    True -> {
      let len = list.length(batch)
      case len / workers {
        0 -> 1
        n -> n
      }
    }
    False -> list.length(batch)
  }
  case chunk_size > 0 {
    True -> list.sized_chunk(batch, chunk_size)
    False -> [batch]
  }
}

pub fn aggregate_grads(grads: List(Matrix)) -> Matrix {
  case list.first(grads) {
    Ok(first) -> list.fold(list.drop(grads, 1), first, matrix.add)
    Error(_) -> matrix.ones(1, 1)
  }
}

pub fn main() {
  let batch = list.repeat(matrix.random(1, 10), 100)
  let distributed = distribute_batch(batch, 4)
  io.println("Distributed batch count: " <> int.to_string(list.length(distributed)))
  Nil
}

