import gleam/io
import gleam/list
import gleam/int
import gleam/float
import gleam/result
import gleam/order

pub type Matrix {
  Matrix(rows: Int, cols: Int, data: List(Float))
}

pub fn zeros(rows: Int, cols: Int) -> Matrix {
  let size = rows * cols
  Matrix(rows: rows, cols: cols, data: list.repeat(0.0, size))
}

pub fn ones(rows: Int, cols: Int) -> Matrix {
  let size = rows * cols
  Matrix(rows: rows, cols: cols, data: list.repeat(1.0, size))
}

pub fn random(rows: Int, cols: Int) -> Matrix {
  let size = rows * cols
  Matrix(rows: rows, cols: cols, data: list.repeat(0.0, size) |> list.map(fn(_) { float.random() }))
}

pub fn add(a: Matrix, b: Matrix) -> Matrix {
  case a.rows == b.rows && a.cols == b.cols {
    True -> {
      let new_data = list.zip(a.data, b.data) |> list.map(fn(pair) {
        pair.0 +. pair.1
      })
      Matrix(rows: a.rows, cols: a.cols, data: new_data)
    }
    False -> a
  }
}

pub fn distribute_batch(batch: List(Matrix), workers: Int) -> List(List(Matrix)) {
  let chunk_size = case workers > 0 {
    True -> {
      let len = list.length(batch)
      case len / workers {
        0 -> 1
        n -> n
      }
    }
    False -> list.length(batch)
  }
  case chunk_size > 0 {
    True -> list.sized_chunk(batch, into: chunk_size)
    False -> [batch]
  }
}

pub fn aggregate_grads(grads: List(Matrix)) -> Matrix {
  case list.first(grads) {
    Ok(first) -> list.fold(list.drop(grads, 1), first, add)
    Error(_) -> ones(1, 1)
  }
}

pub fn main() {
  let batch = list.repeat(random(1, 10), 100)
  let distributed = distribute_batch(batch, 4)
  io.println("Distributed batch count: " <> int.to_string(list.length(distributed)))
  Nil
}
